const input=document.querySelector('#search'),panel=document.querySelector('#results'),cards=document.querySelector('#resultcards'),counter=document.querySelector('#counter');function norm(s){return (s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}input.addEventListener('input',()=>{const q=norm(input.value.trim());if(!q){panel.classList.remove('active');document.querySelector('#catalogo').style.display='';return}panel.classList.add('active');document.querySelector('#catalogo').style.display='none';const terms=q.split(/\s+/).filter(Boolean);let matches=PAGES.filter(p=>terms.every(t=>norm(p.title+' '+p.text).includes(t)));matches.sort((a,b)=>Number(norm(b.title).includes(q))-Number(norm(a.title).includes(q)));counter.textContent=matches.length+' páginas';cards.replaceChildren();for(const p of matches){let a=document.createElement('a');a.className='card';a.href=p.file;let strong=document.createElement('strong');strong.textContent=p.title;let sub=document.createElement('span');sub.textContent=p.category+' • Abrir página';a.append(strong,sub);cards.append(a)}if(!matches.length){cards.textContent='Nenhuma página encontrada.'}});